insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_chemistry', 5, '5.11', array['5.11']::text[], 'vocabulary', 'Catalyst in a mechanism', 'A catalyst''s net concentration is constant; it is frequently consumed in the rate-determining step and regenerated in a subsequent step.', '[]'::jsonb, NULL, 'Cite the step evidence: the catalyst is consumed as a reactant in one step, regenerated as a product in a later step, and absent from the overall equation. Do not confuse it with an intermediate.', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-chem-u5-u9-2026-10-10; candidate=ap_chemistry-u5-r1-029; ced=5.11.A.2 "the net concentration of the catalyst is constant"')
