insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_chemistry', 5, '5.11', array['5.11']::text[], 'convention', 'How a catalyst increases rate', 'A catalyst must increase the number of effective collisions and/or provide a reaction path with a lower activation energy relative to the original reaction coordinate.', '[]'::jsonb, NULL, 'A complete answer cites the specific effect (more effective collisions or an alternate lower-Ea path), not just ''it speeds up the reaction''.', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-chem-u5-u9-2026-10-10; candidate=ap_chemistry-u5-r1-028; ced=5.11.A.1 "increase the number of effective collisions and/or provide a reaction path with a lower activation energy"')
